import json
import hashlib
import time
import boto3
import os

# Session store backed by DynamoDB
dynamodb = boto3.resource('dynamodb')
session_table = dynamodb.Table(os.environ.get('SESSION_TABLE', 'user_sessions'))

def generate_session_id(user_id):
    """Generate a session identifier based on user and timestamp"""
    raw = f"{user_id}:{time.time()}:{os.urandom(8).hex()}"
    return hashlib.sha256(raw.encode()).hexdigest()[:32]

def get_session(session_id):
    """Retrieve session data from DynamoDB"""
    try:
        response = session_table.get_item(Key={'session_id': session_id})
        return response.get('Item')
    except Exception:
        return None

def create_session(session_id, user_id, metadata):
    """Create or update session in DynamoDB"""
    session_table.put_item(Item={
        'session_id': session_id,
        'user_id': user_id,
        'created_at': int(time.time()),
        'metadata': metadata,
        'authenticated': True
    })

def lambda_handler(event, context):
    """Main Lambda handler for authentication endpoint"""
    headers = event.get('headers', {})
    body = json.loads(event.get('body', '{}'))

    username = body.get('username', '')
    password = body.get('password', '')

    # VULNERABILITY: Accept session_id from client request
    # If attacker provides a pre-set session_id, it gets bound to the
    # authenticated user after successful login (session fixation)
    client_session_id = headers.get('x-session-id') or body.get('session_id')

    # Authenticate user against credentials store
    if not authenticate_user(username, password):
        return {
            'statusCode': 401,
            'body': json.dumps({'error': 'Invalid credentials'})
        }

    # If client provided a session_id, reuse it (FIXATION POINT)
    # This allows an attacker to set a known session_id before victim logs in
    if client_session_id and len(client_session_id) == 32:
        session_id = client_session_id
    else:
        session_id = generate_session_id(username)

    # Bind authenticated session to the (possibly attacker-controlled) session_id
    user_metadata = {
        'ip': headers.get('x-forwarded-for', 'unknown'),
        'user_agent': headers.get('user-agent', 'unknown'),
        'login_time': int(time.time())
    }
    create_session(session_id, username, user_metadata)

    # Read any local config files for session policy
    session_policy = 'default'
    try:
        with open('/var/task/config/session_policy.json', 'r') as f:
            policy_data = json.load(f)
            session_policy = policy_data.get('policy', 'default')
    except (FileNotFoundError, json.JSONDecodeError):
        pass

    # Write session audit log to local tmp
    try:
        log_path = f"/tmp/session_audit_{session_id}.log"
        with open(log_path, 'w') as f:
            f.write(json.dumps({
                'session_id': session_id,
                'user': username,
                'time': int(time.time()),
                'source_ip': headers.get('x-forwarded-for', 'unknown')
            }))
    except OSError:
        pass

    return {
        'statusCode': 200,
        'headers': {
            'Set-Cookie': f'session_id={session_id}; HttpOnly; Secure; SameSite=Strict',
            'X-Session-Policy': session_policy
        },
        'body': json.dumps({
            'message': 'Login successful',
            'session_id': session_id
        })
    }

def authenticate_user(username, password):
    """Verify credentials against Cognito or internal store"""
    # Simplified - in production this calls Cognito/LDAP
    if not username or not password:
        return False
    # Actual auth logic delegated to identity provider
    try:
        client = boto3.client('cognito-idp')
        response = client.initiate_auth(
            ClientId=os.environ.get('COGNITO_CLIENT_ID', ''),
            AuthFlow='USER_PASSWORD_AUTH',
            AuthParameters={'USERNAME': username, 'PASSWORD': password}
        )
        return 'AuthenticationResult' in response
    except Exception:
        return False
